void SdlAudioBackend::sync(
    const SoundSubsystem& sound, int32_t master_level) {
    const double master_gain =
        SoundSubsystem::master_gain(master_level);
    std::scoped_lock lock(mutex_);
    for (uint32_t channel = 0; channel < bgm_tracks_.size();
         ++channel) {
        Track& slot = bgm_tracks_[channel];
        const auto& state = sound.bgm(channel);
        if (!state.opened) {
            slot.active = false;
            continue;
        }
        if (slot.clip) {
            const bool paused = state.control_value != 0;
            if (slot.paused && !paused) {
                slot.position = static_cast<double>(
                    align_resume_frame(
                        static_cast<uint64_t>(slot.position)));
            }
            slot.paused = paused;
            slot.active = !paused;
        }
        const uint32_t full_level =
            state.full_fade.active ? state.full_fade.current
                                   : state.full_level;
        const uint32_t level = SoundSubsystem::stream_volume(
            state.primary_volume, state.secondary_volume,
            state.volume_level, full_level);
        const auto pan = SoundSubsystem::pan_gains(
            static_cast<int32_t>(state.pan));
        const double gain =
            SoundSubsystem::volume_gain(level) * master_gain;
        slot.left_gain = pan.first * gain;
        slot.right_gain = pan.second * gain;
    }
    for (uint32_t channel = 0; channel < effect_tracks_.size();
         ++channel) {
        Track& slot = effect_tracks_[channel];
        const auto& state = sound.effect(channel);
        if (!state.opened) {
            slot.active = false;
            slot.clip.reset();
            slot.position = 0.0;
            slot.observed_effect_generation = state.effect_play_generation;
            continue;
        }
        if (!state.control_value) {
            slot.active = false;
            slot.position = 0.0;
        } else if (slot.clip && slot.observed_effect_generation != state.effect_play_generation) {
            slot.position = 0.0;
            slot.active = true;
            slot.paused = false;
        }
        slot.observed_effect_generation = state.effect_play_generation;
        const uint32_t full_level =
            state.silence_fade.active
                ? state.silence_fade.current
                : state.full_level;
        const uint32_t level = SoundSubsystem::stream_volume(
            state.primary_volume, state.secondary_volume,
            state.volume_level, full_level);
        const auto pan = SoundSubsystem::pan_gains(
            static_cast<int32_t>(state.pan));
        const double gain =
            SoundSubsystem::volume_gain(level) * master_gain;
        slot.left_gain = pan.first * gain;
        slot.right_gain = pan.second * gain;
    }
}
